g.metadata:
{
  "schema": "ppt-master.semantic-table.v2",
  "name": "limits-table",
  "x": 64, "y": 196, "width": 1152, "height": 450,
  "strict_grid": true,
  "column_widths": [190, 500, 462],
  "row_heights": [36, 54, 72, 54, 54, 54, 54, 72],
  "style": {
    "font_family": "Calibri",
    "font_size": 16,
    "header_fill": "#003657",
    "header_text": "#FBF8F2",
    "body_text": "#1E1E1E",
    "band_row": false,
    "valign": "middle"
  },
  "defaults": {
    "cell": {
      "padding": {"left": 12, "right": 12, "top": 4, "bottom": 4},
      "borders": {
        "left": {"style": "none"}, "right": {"style": "none"},
        "top": {"style": "solid", "color": "#D6CFC2", "width": 1},
        "bottom": {"style": "solid", "color": "#D6CFC2", "width": 1}
      }
    }
  },
  "columns": [
    {"text": "Issue", "bold": true, "align": "l"},
    {"text": "What we know", "bold": true, "align": "l"},
    {"text": "Implication", "bold": true, "align": "l"}
  ],
  "rows": [
    [
      {"text": "Growth and discount rate", "bold": true, "color": "#003657"},
      {"text": "20% and 15% are identified as Prep Q3 assumptions"},
      {"text": "Base-case value is conditional; sensitivity matters."}
    ],
    [
      {"text": "Decision date", "bold": true, "color": "#003657", "fill": "#F1ECE2"},
      {"text": "The workbook's economic comparison starts at inception", "fill": "#F1ECE2"},
      {"text": "A December valuation must preserve sunk contributions and model only changed future rights and obligations.", "fill": "#F1ECE2"}
    ],
    [
      {"text": "Deployment", "bold": true, "color": "#003657"},
      {"text": "Five equal 20% draws are modeled; case contributions to date are only 10.7% of commitment"},
      {"text": "Different timing can change returns and fee drag; recalculate the direction rather than assert it."}
    ],
    [
      {"text": "Actual agreement", "bold": true, "color": "#003657", "fill": "#F1ECE2"},
      {"text": "Exact VI hurdle, catch-up and cancellation terms are not established here", "fill": "#F1ECE2"},
      {"text": "Confirm terms before claiming a concession is new or valuing cancellation.", "fill": "#F1ECE2"}
    ],
    [
      {"text": "Simplifications", "bold": true, "color": "#003657"},
      {"text": "GP co-investment, fee offsets, fee step-downs, financing detail, clawback detail and taxes are omitted"},
      {"text": "Results explain the assigned framework, not every feature of the live fund."}
    ],
    [
      {"text": "Valuation uncertainty", "bold": true, "color": "#003657", "fill": "#F1ECE2"},
      {"text": "Private investment values are estimates; the case reports early losses", "fill": "#F1ECE2"},
      {"text": "Review current information without using later write-down announcements.", "fill": "#F1ECE2"}
    ],
    [
      {"text": "Calculation checks", "bold": true, "color": "#003657"},
      {"text": "Five main scenarios and their 31-point growth grids were independently reproduced for core returns, NPV and GP compensation"},
      {"text": "Supports arithmetic consistency; does not validate forecasts or every native Excel feature."}
    ]
  ]
}
